# Ronde G3: recht en wetten + dagelijks leven (idempotent)
from gaten_lib import Ronde,GR
R=Ronde(3);A=R.add
W='Wetten'
RECHT=[
('RECHT-tribunaal','Tribunaal van drie Moeders','Hoogste rechtbank per stad: drie Moeders, openbaar op Ontvangstdag. Functie: recht als geloof; vonnis is gebed. Haak: een Moeder in het tribunaal is omkoopbaar (intrige).','WET-wetten-straffen;RIT-tribunaal-drie'),
('RECHT-dorpsraad','Moederraad van het dorp','Lage rechtspraak: de oudste vrouwen van de moederhuizen beslechten burenruzie, stalgeschil en diefstal. Nuchter en snel; mannen hebben er geen stem.','CUL-gezin-wonen;REG-ambergaard'),
('RECHT-huisrecht','Huisgerecht','Huizen (Varenne, Kaldra, Mirre) berechten hun eigen leden en bezit; Kaldra met krijgsrecht, Varenne met contractrecht, Mirre met scheepsrecht. Conflict met de Orde over wie een gestolen man berecht.','HUI-varenne;HUI-kaldra;HUI-mirre'),
('RECHT-gavenrecht','Recht voor gaven-mannen','Gaven-mannen staan buiten het gewone recht: alleen de Hoge Moeder kan hen berechten. Straf: kluis (opsluiting in een tempelcel met dagelijkse ontvangsten) of ontzegging. Haak: een gaven-man die moordt en vrijuit gaat (thriller).','MACHT-gaven-mannen;WET-wetten-straffen'),
('RECHT-rechtsgang','Rechtsgang','Aanklacht door een vrouw of een huis; registerbewijs; getuigen (alleen vrouwen tellen volledig, een man telt half, een gewone man een tiende); vonnis; boete of straf; beroep bij de Hoge Moeder tegen betaling van een gunstbrief. Haak: wie geen gunstbrief heeft, krijgt geen tweede kans.','RECHT-tribunaal;ECO-geld'),
('RECHT-bewijs','Bewijs','Registerbewijs boven alles; daarna merk en bloedspiegel (LICH-bloedspiegel); dan getuigen; dan de Lampenproef (een Ysa-lamp die gloeit bij leugens: in feite flikkert ze bij zegellicht, dus fraudegevoelig). Haak: een vervalst register wint altijd van de waarheid.','LICH-bloedspiegel;VOORW-lampen;VOORW-register'),
('RECHT-advocaat','Pleitzusters','Novicen die voor geld pleiten; de beste werken voor Varenne. Een pleitzuster die voor een gewone man pleit, is een schandaal (romance+intrige).','ORDE-opleiding;HUI-varenne'),
('STRAF-boete','Straf: boete en tiende','Voor kleine vergrijpen: Druppels of gunstbrieven; vaak omgezet in diensturen in een stal of tempel.','ECO-geld'),
('STRAF-brandmerk','Straf: brandmerk','Voor zaad- en registerbedrog: een merk op wang of hand; het brandmerk draagt Sterrensteen-inkt en dooft nooit. Wie gemerkt is, krijgt geen gunstbrief meer.','LICH-merkweefsel;WET-wetten-straffen'),
('STRAF-schandpodium','Straf: het Schandpodium','Openbare tentoonstelling, soms met verplichte rite voor publiek (volwassenen; donker thema). Functie: afschrikking en vermaak.','RIT-schandpodium;PLEK-LICH-schandpodium'),
('STRAF-verbanning','Straf: verbanning naar de rand','Uit het register geschrapt en naar de Asvelden of randdorpen; je bestaat niet meer. Velen worden Uitgestotenen.','DEG-uitgestotenen;PLEK-RAND-randdorp'),
('STRAF-dood','Straf: de dood','Voor het doden van een man, ontvoering van een gaven-man, verwantschapsseks (soms) en hoogverraad. Executie door verdrinking in de Ysmer (vrouwen) of door Leegte (opsluiten zonder zaad tot de dood; gebonden vrouwen).','WET-wetten-straffen'),
('STRAF-stal','Straf voor mannen: de stal','Een vrije man die een misdaad begaat, wordt stalman; een stalman die vlucht, krijgt Ankerwortel of wordt verkocht aan Varenne. Donker thema.','KOE-ankerwortel;KOE-melkos'),
('STRAF-lijngraver','Straf: de lijn','Sinds 760 laat Kaldra en Kharvos zwaar gestraften als Lijngraver "geven" (verplichting). In de canon: misdaad van het systeem.','LIJN-voorinstemming;LIJN-recht-kharvos'),
('GEV-zoutkelders','Gevangenis: de Zoutkelders van Brakhaven','Natte kelders onder de haven; bij vloed staan gevangenen tot hun borst in zout water. Mirre koopt hier bemanning. Haak: ontsnapping via een Oevrin-slikgang.','REG-zoutkust;VOLK-oevrin'),
('GEV-kerkers-saelith','Gevangenis: de kerkers van Saelith','Onder de tempel; hier ligt de versteende Orric en zitten ketters. Stille Hand-verhoren. Haak: wie hier zit, hoort de Zegel zoemen.','PLEK-LICH-bloedkerker;LICH-orric-steen;ORDE-stille-hand'),
('GEV-ijskooi','Gevangenis: de Ijskooien van Kaldrun','Kooien op een gletsjer voor deserteurs en Kharvos-gevangenen; Karrûk-gevangenen houden het er het langst vol.','REG-hoogvrouwe;VOLK-karrûk'),
('GEV-zandput','Gevangenis: de Zandput van Qesh','Een open put; Khaled-Ir laat gevangenen vrij als ze een seizoen in zijn harem dienen (volwassen, keuze onder druk: donker thema).','REG-rosse;PER-khaled')]
for c_,o,f,r in RECHT: A(c_,W,o,f+GR,'recht',r,functie='CTRL;POL')
WIE=[('vrouw','Wie mag wat: de vrouw','Mag bezit hebben, erven, handelen, vechten, besturen, een gewone man kopen en weigeren (tegen kosten: WET-wie-weigert). Mag niet: een gaven-man weigeren zonder rangverlies, zaad buiten register verhandelen, een man doden.'),
('gewone-man','Wie mag wat: de gewone man','Mag niet bezitten, niet getuigen (een tiende), niet reizen zonder halsband en papier, niet weigeren te dekken. Mag: eten, slapen, één dag rust per maan (Melkzegen), een klacht indienen via zijn eigenares. Vrije mannen in de Zoutkust: mogen zich verhuren, belast.'),
('gaven-man','Wie mag wat: de gaven-man','Mag kiezen wie hij ontvangt, reizen in rotatie, bezit houden via de Orde. Mag niet: de rotatie weigeren, een gebonden vrouw dwingen (sinds Aeron-as\' weigering omstreden), zijn zaad verkopen buiten de Orde.'),
('lijngraver','Wie mag wat: de Lijngraver','Fase 1: alle rechten van een vrouw of man, kan nog stoppen. Vanaf fase 2: juridisch eigendom van de eigenaar. In de canon: onrecht; de Losmakers procederen soms namens fase-1-gravers.'),
('koe','Wie mag wat: de superkoe','Juridisch vee met een naam; geen rechten; beschermd alleen als bezit (wie hem beschadigt betaalt de eigenaar). Donker thema; in de canon onrecht.'),
('vreemd-volk','Wie mag wat: de andere volken','Aelthir, Dhurn en Sael-mor: gastrecht met pas. Kluwer, Oevrin, Myrrhen: geduld zonder rechten. Orrim: officieel beschermd, feitelijk geoogst. Vathren en Ves-Lethi: vogelvrij.')]
for s,o,f in WIE: A(f'WET-wie-{s}',W,o,f+GR,'wie mag wat','WET-wie-weigert;MACHT-twee-soorten-mannen',functie='CTRL;ID')
WR=[('saelith','Strengst: registerplicht bij elke ontvangst, avondklok voor mannen, verbod op vreemde volken binnen de eilanden.'),('ambergaard','Stalrecht: een collectief mag een man houden; het Oogstbed is wettelijk geregeld (loting).'),('hoogvrouwe','Krijgsrecht in de winter; duel om een man is wettig.'),('zoutkust','Vrije mannen mogen zich verhuren; havenrecht van Mirre; smokkel is officieel verboden, feitelijk belast.'),('groenmuil','Nauwelijks Orde-recht; stamrecht van Kluwers en Aelthir; Grijswortel groeit hier vrij.'),('rosse','Recht van de Zonvorst; harem-recht; Ishvar-huwelijk erkend.'),('kharvos','Mannenrecht: vrouwen zijn bezit; krijgsrecht over gevangenen; Lijngraver-straf.'),('stille','Zusterrecht: mannen mogen het eiland niet betreden; bewaard zaad is gemeenschapsbezit.')]
for g,f in WR: A(f'WET-reg-{g}',W,f'Wetten in {g.capitalize()}',f+GR,'wetten per regio',f'REG-{g}',functie='CTRL')
WV=[('volk-aelthir','Aelthir-recht: het Lange Geheugen is wet; liegen over het verleden is de zwaarste misdaad (ironie: zij zwijgen).','VOLK-aelthir'),('volk-dhurn','Dhurn-gilderecht: inteelt-toezicht door gildemoeders; wie met een te nauwe verwant paart, verliest zijn gilde.','VOLK-dhurn'),('volk-karruk','Karrûk-vuurrecht: geschillen in het Vuurkamp; de winnares heeft gelijk.','VOLK-karrûk'),('volk-kluwer','Korfrecht: de Broedmoeder beslist alles; buitenstaanders die de korf bezoeken, moeten instemmen voor elk ritueel.','VOLK-kluwer'),('volk-ishvar','Ishvar-recht: de Twee-gelofte is onbreekbaar; ontrouw is de enige misdaad die verbanning kost.','VOLK-ishvar')]
for s,f,r in WV: A(f'WET-{s}',W,f'Recht van een volk ({s[5:]})',f+GR,'wetten per volk',r,functie='CTRL;ID')
OV=[('WET-deelwet-recht','Deelwet- en huwelijksrecht','Geen huwelijk met mannen; wel het Moederhuisverbond tussen vrouwen (erfrecht, voogdij). Een gewone man kan in "deelbezit" van meerdere vrouwen zijn. Gaven-mannen kunnen geen verbond sluiten. Ishvar-huwelijk alleen in Qesh. Haak: twee vrouwen in een verbond die beiden dezelfde man liefhebben (romance, jaloezie).','GEB-deelwet;CUL-gezin-wonen'),
('WET-erfrecht','Eigendom en erfrecht','Erfrecht via de moeder. Mannen zijn bezit en erven mee als "levend goed". Gunstbrieven zijn erfbaar maar niet deelbaar. Haak: een erfeniszaak om een stalman die ook een geliefde is.','REGEL-overwegend-vrouwelijke-wereld;ECO-geld'),
('WET-smokkel','Smokkelrecht','Smokkel van zaad, mannen, Grijswortel en vrouwen uit Kharvos: officieel brandmerk of dood; feitelijk betalen smokkelaars Mirre een tiende. Haak: elke smokkelaar is een potentiële spion.','HUI-mirre;ECO-wat-wordt-verhandeld'),
('WET-grijswortel','Verbodswet Grijswortel (740)','Bezit is een brandmerk, handel is de dood: Grijswortel breekt binding en dus macht. Groeit in Groenmuil. Haak: elke gebonden vrouw die vrij wil, moet een misdaad begaan.','GEB-r10-grijswortel-verbod;MAGIE-verslaving'),
('WET-ankerwortel','Ankerwortel: geen wet','Ankerwortel is nergens verboden, omdat officieel niemand weet dat het bestaat; in de stallen heet het "stalkruid". Haak: wie het bewijst, kan de stallen laten vallen.','KOE-ankerwortel'),
('WET-registerplicht','Registerplicht','Elke ontvangst door een geregistreerde man wordt opgetekend; elke geboorte binnen 7 dagen. Weglaten: boete; vervalsen: brandmerk; verwantschap verzwijgen: dood.','REGEL-registers-merken;LEER-bloedzuiverheid')]
for c_,o,f,r in OV: A(c_,W,o,f+GR,'specifieke wetten',r,functie='CTRL;ECO')
# --- dagelijks leven ---
D=[('Cultuur','DAG-eten-gewoon','Eten van gewone mensen','Ontbijt: graanpap met honing; middag: brood, kaas, zoute vis of bonen; avond: stoofpot. Feestmaal: geroosterde gans, amberbier. Mannen krijgen "mannenvoer" (oesters, eieren, bonen) als voederregime. Herkenbaar als middeleeuws-mediterraan; vreemd zijn alleen Kluwer-honing en Myrrhen-zwam.','CUL-eten-kunst-bijgeloof'),
('Cultuur','DAG-eten-regio','Eten per regio','Saelith: rivierkreeft, vijgen. Ambergaard: brood, bier, worst. Hoogvrouwe: gedroogd vlees, zuurkool, berenvet. Zoutkust: vis, zeewier, rum. Groenmuil: vruchten, insecten, Kluwer-honing. Rosse: dadels, gekruide geit, munt-thee.','REG-overzicht'),
('Economie','DAG-landbouw','Landbouw','Graan en bonen in Ambergaard, rijst in de delta, olijven en wijn aan de zuidrand. Vrouwen ploegen met ossen; boerinnencollectieven delen land, molen en stalman. Misoogst betekent: een stalman verkopen.','REG-ambergaard;ECO-wie-werkt'),
('Cultuur','DAG-wonen','Wonen','Moederhuizen: een binnenplaats met kamers rondom, een gemeenschappelijke keuken en een stalhuis achterin voor de gewone man. In steden smalle huizen met een "mannenkamer" op slot. Rijken hebben een gunstkamer voor bezoek van een gaven-man.','CUL-gezin-wonen'),
('Economie','DAG-werk','Werk en beroepen','Vrouwen: boerin, smid, mijnwerkster, krijgsvrouw, koopvrouw, schipper, vroedvrouw, Registratrix, pleitzuster, lampenmaker, bakster, veerman (soms vrije mannen), herbergierster. Gilden: bakkers, smeden, lampenmakers, schrijvers, Dhurn-steengilde. Mannen: dekken; vrije mannen in de Zoutkust: roeier, herbergier, huurman.','ECO-wie-werkt;PER-gew-kara;PER-gew-oswin'),
('Mode en kleding','DAG-kleding','Kleding van gewone mensen','Werkvrouwen: linnen hemd, leren schort, broek of rok, sjerp in rangkleur. Winter: wol en bont. Mannen: tuniek en halsband; vrije mannen een oorring als teken van eigen bezit. Feest: geborduurde sjerp, lampjes in het haar.','CUL-kleding;VOORW-halsband'),
('Gezondheid','DAG-gezondheid','Gezondheid en geneeskunde','Kruidenvrouwen en vroedvrouwen; tempelheelsters voor de rijken. Ziekten: koorts, steenlong (mijnen), zaadslijtage (mannen), Leegteziekte, Pest-littekens. Middelen: Maankruid (anticonceptie), Grijswortel (verboden), Kluwer-was (zalf), Myrrhen-zwam (verboden). Kraambed is het grootste gevaar voor vrouwen.','LICH-zaadslijtage;LICH-leegteziekte;REG-groenmuil'),
('Cultuur','DAG-opvoeding','Opvoeding en school','Meisjes leren in het moederhuis en op de tempelschool: lezen, rekenen, het register van hun eigen lijn, een ambacht. Jongens gaan op hun zesde naar het Jongenshof (les, sport, zorg; geen seksuele rol). Op 18 de Wijding. Haak: het gemis van een broer of zoon is een gewoon, herkenbaar verdriet.','CUL-wat-jongens-meemaken;RIT-wijding'),
('Cultuur','DAG-dood','Dood en begrafenis','Vrouwen worden verbrand en hun as in de Ysmer gestrooid; hun naam blijft in het register. Gewone mannen worden in de stalgrond begraven, zonder naam (stalnaam op een paal). Gaven-mannen in een tempelcrypte. Doodgeboren jongens krijgen in de Stilmaan een lampje.','FEEST-stilmaan;LEER-hiernamaals'),
('Cultuur','DAG-muziek','Muziek en kunst','Harp en trommel in tempels; ballades over Tesk de Melkknecht en de Honderd Dochters; vrouwenkoren; stalliederen van mannen (verboden teksten over vrijheid). Theater: Ontvangst-spelen en satire op gaven-mannen in Brakhaven.','PER-tesk;GOD-dochters-heiligen'),
('Cultuur','DAG-feesten-volks','Volksfeesten','Behalve de Orde-feesten: marktdagen, de Zoutkust-havenkermis, de Oogstnacht, een "mannenmarkt" in Merk, schaatsfeesten in Hoogvrouwe. Plekken voor romance: de dans op de Oogstnacht, waar je je partner niet hoeft te kiezen via het register.','FEEST-oogstnacht;KAL-kalender'),
('Cultuur','DAG-spel','Spel en ontspanning','Bordspel "Register" (lijnen verbinden zonder verwantschap), dobbelen, worstelen, paardrijden, schaatsen, zwemmen. Weddenschappen op welke vrouw een gaven-man kiest.','RIT-veiling'),
('Cultuur','DAG-taal-schelden','Taal en schelden','Scheldwoorden: "droog" (zonder zaad), "neefkind" (ingeteeld), "lamploze" (ongelovig), "stalvlees", "made" (Lijngraver), "glad" (verdacht). Groet: "Ysa kijkt". Vloek: "bij de Wrede Vaders". Liefkozing: "mijn lamp".','CUL-taal-namen;LIJN-overzicht;DEG-gladden'),
('Economie','DAG-prijzen','Geld en prijzen','Brood: 1/10 Druppel. Een maaltijd in een herberg: 1/4 Druppel. Een paard: 4 Kronen. Een kamer per nacht: 1/2 Druppel. Huur van een gewone man per nacht: 3-10 Druppels. Gunstbrief op de zwarte markt: 30-500 Kronen. Grijswortel: 2 Kronen per dosis (zwarte markt).','ECO-geld;ECO-prijzen-mannen-zaad'),
('Economie','DAG-vervoer','Vervoer','Barken op de Ysmer, karavanen in de Rosse, muildieren in de bergen, schepen van Mirre langs de kust, Skerra-koeriers voor berichten, Oevrin-sleepboten door het slik. Gaven-mannen reizen in gesloten draagstoelen met tempelwacht. Reizen duurt: zie G4-kaart.','VOLK-skerra;VOLK-oevrin'),
('Cultuur','DAG-liefde-gewoon','Gewone liefde en jaloezie','Het herkenbare hart van de wereld: vrouwen worden verliefd op elkaar en op mannen die ze niet mogen hebben; jaloezie op wie een gunstbrief krijgt; schaamte over een stalman liefhebben; loyaliteit aan het moederhuis; ambitie voor een dochter. Dit is de toegangsdeur voor de lezer.','CUL-gezin-wonen;HAAK-PER-romance'),
('Cultuur','DAG-dag-vrouw','Een gewone dag van een vrouw','Vroeg op, stal en vee, markt of werkplaats, middag in het moederhuis, avond in de herberg of tempel. Ontvangstdag: tempel en feest. Zorgen: geld, kinderen, een zoon die naar het Hof moet, de wachtlijst.','DAG-wonen;DAG-werk'),
('Cultuur','DAG-dag-man','Een gewone dag van een gewone man','Wakker in het stalhuis, mannenvoer, 2-4 dekkingen of melkingen, wassen, rust; soms een liefde, vaak verveling en schaamte; dromen van de Stal van Ysa. Donker thema waar dwang speelt.','ECO-wie-werkt;KOE-melkos-toestemming'),
('Cultuur','DAG-herberg','De herberg','Overal het sociale hart: vrouwen drinken, gokken, kopen geruchten; achterkamers voor vrije mannen (Zoutkust); kijkgaten (Jorrit). Scènes: intrige, romance, gevecht.','PER-gew-jorrit'),
('Cultuur','DAG-humor','Humor en spot','Grappen over ijdele gaven-mannen, stijve Registratrices en "droge" Moeders. Satire is een uitlaatklep die de Orde gedoogt, tot ze te scherp wordt.','DAG-muziek')]
for cat,c_,o,f,r in D: A(c_,cat,o,f+GR,'dagelijks leven',r,functie='ID')
# dagelijks leven per volk (kort, vreemd als contrast)
VD=[('aelthir','Leven in boomhallen; eten weinig, slapen weken in de winter.'),('karrûk','Kampen rond vuren; eten rauw vlees; kinderen vechten om rang (geen seksuele rol).'),('dhurn','Mijnsteden; warme baden; gilde-eten met zout en bier.'),('sael-mor','Schepen; vis rauw; zingen bij elk getij.'),('grauwen','Randdorpen; zorg voor elkaar; gedeelde kookpot.'),('ishvar','Tenten in kleine families; munt-thee; zon-gebeden.'),('vathren','Verborgen kampen; zwijgen; tellen de hartslag van de Zegel.'),('kluwer','Korven van was; honing als munt.'),('myrrhen','Veenhallen; eten niet maar nemen op uit de schimmel.'),('oevrin','Sliktunnels; eten aal en kuit.'),('tharn','Dijkdorpen; een Tharn eet als tien mensen.'),('orrim','Grotten; eten zout en mineralen.'),('skerra','Klifnesten; vliegen elke ochtend.'),('ves-lethi','Leven tussen andere volken in vermomming.')]
for v,f in VD: A(f'DAG-volk-{v.replace("û","u")}','Cultuur',f'Dagelijks leven: {v}',f+GR,'dagelijks leven per volk','VOLK-'+('karrûk' if v=='karrûk' else v),functie='ID')
A('HAAK-G3-overzicht','Verhaal','Verhaalhaken uit recht en dagelijks leven','Romance: een pleitzuster en een gewone man; twee verbondsvrouwen en één stalman. Intrige: een omkoopbaar tribunaal; Varenne-pleitzusters; Ankerwortel-bewijs. Erotiek: herbergachterkamers, de Oogstnacht-dans, Zandput-prijs (donker). Thriller: de Lampenproef faalt bij een lek; ontsnapping uit de Zoutkelders; Grijswortel-smokkel met de doodstraf als klok.'+GR,'genrehaken','RECHT-advocaat;WET-deelwet-recht;RECHT-tribunaal;WET-ankerwortel;DAG-herberg;GEV-zandput;RECHT-bewijs;GEV-zoutkelders;WET-grijswortel')
A('RECHT-gunstrecht','Wetten','Gunstbrief-recht','Wie een gunstbrief vervalst, verliest alle brieven van haar huis; veilingrecht van Varenne erkent de Orde alleen tegen tiende. Haak: een vervalste brief als motor van een heistverhaal.'+GR,'recht','VOORW-gunstbrief;HUI-varenne',functie='ECO;CTRL')
A('RECHT-gastrecht','Wetten','Gastrecht en vrijgeleide','Een herbergierster die een vluchteling drie nachten huisvest, mag hem niet uitleveren (oud Rivier-recht); de Stille Hand respecteert het niet. Haak: drie nachten als klok.'+GR,'recht','DAG-herberg;ORDE-stille-hand',functie='CTRL')
A('DAG-reizen-herbergen','Cultuur','Reizen en onderdak','Reizigsters slapen in tempelherbergen (gratis met registerbewijs) of in karavanserais; een man reist alleen met papier en eigenares. Gevaren: zaadrovers, wolven, tolposten van Kaldra.'+GR,'dagelijks leven','DAG-vervoer;RIT-reizigersgroet',functie='ID')
R.wrij('Lampenproef in de rechtspraak','RECHT-bewijs; VOORW-lampen','Als lampen bij lekken flikkeren, worden onschuldigen bij een lek veroordeeld: bewijs voor de lekken in tribunaalverslagen.','bron van verhalen')
R.wrij('Getuigenwaarde van mannen','RECHT-rechtsgang; WET-wie-gewone-man','Teo en Bram kunnen nauwelijks getuigen; elke waarheid van een man moet via een vrouw.','bron van verhalen')
R.wrij('Ankerwortel niet verboden','WET-ankerwortel; KOE-ankerwortel; WET-grijswortel','Het middel van de stallen is legaal door onzichtbaarheid, het bevrijdende middel is dodelijk verboden.','bron van verhalen')
R.wrij('Lijngraver-straf vs fase-1-rechten','STRAF-lijngraver; WET-wie-lijngraver','Een straf-graver heeft in fase 1 formeel het recht te stoppen; Kaldra negeert dat.','mogelijke fout')
R.vraag('Mogen vrije mannen in de Zoutkust eigendom hebben?','Bepaalt Tobin, Jorrit en Pell.','WET-reg-zoutkust;PER-gew-jorrit')
R.log('recht en wetten (rechtbanken, rechtsgang, bewijs, straffen, gevangenissen, wie mag wat, regio- en volksrecht, Deelwet-, erf-, smokkel- en verbodswetten) en dagelijks leven (eten, landbouw, wonen, werk, kleding, gezondheid, opvoeding, dood, muziek, feesten, spel, taal, prijzen, vervoer, per volk) met genrehaken.')
R.klaar()
